    ["He must have been delayed by something."] = "Должно быть, его что-то задержало.",
    ["Zhou Haitao - Word Search Gameplay"] = "Чжоу Хайтао — игровой процесс поиска слов",
    ["It's alright, get some good rest."] = "Все в порядке, отдохни хорошенько.",
    ["Dragon-hunting thug"] = "Бандит, охотящийся на драконов",
